package com.citacloud.springboot.contacloud.app.services;
import com.citacloud.springboot.contacloud.app.dto.*; import com.citacloud.springboot.contacloud.app.models.*; import com.citacloud.springboot.contacloud.app.repositories.*; import com.citacloud.springboot.contacloud.app.security.TenantContext;
import net.sf.jasperreports.engine.*; import net.sf.jasperreports.engine.data.JRMapCollectionDataSource; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.io.*; import java.time.format.DateTimeFormatter; import java.util.*;
@Service
public class RecuentoCajaPdfService {
 private static final DateTimeFormatter DT=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm"); private final RecuentoCajaService service; private final EmpresaRepository empresas; private final DatosEmpresaRepository datos; private final LocalFileStorageService storage; private volatile JasperReport report;
 public RecuentoCajaPdfService(RecuentoCajaService s,EmpresaRepository e,DatosEmpresaRepository d,LocalFileStorageService st){service=s;empresas=e;datos=d;storage=st;}
 @Transactional(readOnly=true) @PreAuthorize("hasAuthority('recuentos_caja.imprimir')") public ArchivoPdfDto generar(UUID id){var p=TenantContext.principalActual();RecuentoCajaDto r=service.obtener(id);Empresa empresa=empresas.findByIdAndTenantId(p.empresaId(),p.tenantId()).orElseThrow(()->new ReglaNegocioException("No fue posible identificar la empresa."));DatosEmpresa de=datos.findByEmpresaId(p.empresaId()).orElse(null);byte[] logo=empresa.getLogoObjectKey()==null?null:storage.load(empresa.getLogoObjectKey(),5L*1024*1024).orElse(null);Map<String,Object> x=new HashMap<>();x.put("companyName",de==null?empresa.getNombre():first(de.getNombreComercial(),empresa.getNombre()));x.put("companyTaxId",PurchaseOrderPdfService.formatTaxIdentification(empresa.getIdentificacionFiscal()));x.put("companyAddress",de==null?null:de.getDireccion());x.put("companyPhone",de==null?null:PurchaseOrderPdfService.formatPhone(de.getTelefono()));x.put("companyEmail",de==null?null:de.getCorreo());x.put("companyLogo",logo==null?null:new ByteArrayInputStream(logo));x.put("number",r.numero());x.put("cash",r.caja());x.put("branch",r.sucursal());x.put("dateTime",DT.format(r.contadoEn()));x.put("user",r.usuario());x.put("currency",r.monedaCodigo());x.put("expected",r.esperado());x.put("counted",r.contado());x.put("difference",r.diferencia());x.put("result",label(r.resultado()));x.put("notes",r.observacion());Collection<Map<String,?>> rows=new ArrayList<>();r.detalles().forEach(d->rows.add(Map.of("denomination",d.denominacion(),"quantity",d.cantidad(),"subtotal",d.subtotal())));try{byte[] out=JasperExportManager.exportReportToPdf(JasperFillManager.fillReport(reporte(),x,new JRMapCollectionDataSource(rows)));return new ArchivoPdfDto("Recuento_"+r.numero()+".pdf",out);}catch(JRException ex){throw new ReglaNegocioException("No fue posible generar el PDF del recuento.",ex);}}
 private JasperReport reporte(){if(report==null)synchronized(this){if(report==null)try(InputStream in=getClass().getResourceAsStream("/reports/cash-count/cash-count.jrxml")){if(in==null)throw new ReglaNegocioException("No se encontró la plantilla del recuento.");report=JasperCompileManager.compileReport(in);}catch(IOException|JRException ex){throw new ReglaNegocioException("No fue posible compilar la plantilla del recuento.",ex);}}return report;}
 private static String first(String a,String b){return a==null||a.isBlank()?b:a.trim();} private static String label(ResultadoRecuentoCaja r){return switch(r){case BALANCED->"CUADRE CORRECTO";case OVERAGE->"SOBRANTE DE CAJA";case SHORTAGE->"FALTANTE DE CAJA";};}
}
